import numpy as np
from scipy.spatial.transform import Rotation as R

def setup(session):
    global s,m,d,robot,ctrl,ee,fx,joints,handles
    s=session; m=s.model; d=s.data; robot=s.env.robots[0]; ctrl=robot.part_controllers['right']
    ee=m.site('gripper0_right_grip_site').id
    fx=s.env.door_fxtr
    joints={side:m.joint(f'{fx.name}_{side}doorhinge').id for side in ('left','right')}
    handles={side:m.geom(getattr(fx,side+'_handle_name')).id for side in ('left','right')}

def pose():
    return d.site_xpos[ee].copy(),d.site_xmat[ee].reshape(3,3).copy()

def angles():
    return {side:round(float(d.qpos[m.jnt_qposadr[j]])*180/np.pi,2) for side,j in joints.items()}

def handle(side):
    return d.geom_xpos[handles[side]].copy()

def act(p=None,mat=None,grip=-1,base=None,torso=0,mode=-1,gain=1,rotgain=1):
    a=np.zeros(12); a[6]=grip; a[10]=torso;a[11]=mode
    pos,ori=pose(); B=ctrl.origin_ori
    if p is not None:a[:3]=np.clip(B.T@(np.asarray(p)-pos)*gain/.05,-1,1)
    if mat is not None:a[3:6]=np.clip(B.T@R.from_matrix(mat@ori.T).as_rotvec()*rotgain/.5,-1,1)
    if base is not None:a[7:10]=base
    return s.step(a)

def move(p,mat=None,n=80,grip=-1,torso=0,base=None,mode=-1,tol=.003):
    for i in range(n):
        act(p,mat,grip,base,torso,mode)
        pos,ori=pose()
        if i>10 and np.linalg.norm(pos-p)<tol and (mat is None or np.linalg.norm(R.from_matrix(mat@ori.T).as_rotvec())<.025):break
    print('move',len(s.actions),'err',np.round(np.asarray(p)-pose()[0],4),'pos',np.round(pose()[0],4),'angles',angles(),flush=True)

